// Process absent students

// Step 1: Get data from both Google Sheets
const attendanceRecords = $('Read Today\'s Attendance1').all();
const studentContacts = $('Read Student Contacts1').all();

const absentStudentsOutput = [];
const today = new Date().toISOString().split('T')[0];

// Step 2: Check every attendance record
for (const record of attendanceRecords) {
  const attendance = record.json;

  // Only process unexcused absences
  if (attendance.Status === 'Absent') {
    const student = studentContacts.find(s => s.json['Student ID'] === attendance['Student ID']);

    if (student) {
      const studentData = student.json;

      const thirtyDaysAgo = new Date();
      thirtyDaysAgo.setDate(thirtyDaysAgo.getDate() - 30);
      const thirtyDaysAgoString = thirtyDaysAgo.toISOString().split('T')[0];

      const recentAbsences = attendanceRecords.filter(r => 
        r.json['Student ID'] === attendance['Student ID'] && 
        r.json.Status === 'Absent' && 
        r.json.Date >= thirtyDaysAgoString
      ).length;

      const totalDays = 30;
      const presentDays = totalDays - recentAbsences;
      const attendanceRate = Math.round((Math.max(0, presentDays) / totalDays) * 100);

      let alertLevel;
      if (recentAbsences >= 5) {
        alertLevel = 'High';
      } else if (recentAbsences >= 3) {
        alertLevel = 'Medium';
      } else if (recentAbsences > 0) {
        alertLevel = 'Low';
      } else {
        alertLevel = 'None';
      }

      absentStudentsOutput.push({
        studentId: attendance['Student ID'],
        studentName: studentData.Name,
        parentEmail: studentData.Email,
        parentPhone: studentData.Phone,
        absentDate: today,
        recentAbsences: recentAbsences,
        attendanceRate: attendanceRate,
        alertLevel: alertLevel
      });
    }
  }
}

// Remove duplicate students from the list
const uniqueAbsentStudents = absentStudentsOutput.filter((student, index, self) =>
  index === self.findIndex((s) => (
    s.studentId === student.studentId
  ))
);

// Step 3: Return the final unique list to the next node
return uniqueAbsentStudents.map(item => ({ json: item }));

