// Generate the daily attendance report

// Step 1: Get the unique list of absent students from the previous node
const absentStudents = $input.all();

// If no student is absent, return an empty report
if (absentStudents.length === 0) {
  return [{
    json: {
      date: new Date().toISOString().split('T')[0],
      totalAbsences: 0,
      highAlerts: 0,
      mediumAlerts: 0,
      lowAlerts: 0,
      averageAttendanceRate: 100,
      studentsAtRisk: "None"
    }
  }];
}

const today = new Date().toISOString().split('T')[0];

// Step 2: Build the report summary
const attendanceReport = {
  date: today,

  // totalAbsences is the number of unique absent students from the previous node
  totalAbsences: absentStudents.length,

  highAlerts: absentStudents.filter(s => s.json.alertLevel === 'High').length,
  mediumAlerts: absentStudents.filter(s => s.json.alertLevel === 'Medium').length,
  lowAlerts: absentStudents.filter(s => s.json.alertLevel === 'Low').length,

  averageAttendanceRate: Math.round(
    absentStudents.reduce((sum, s) => sum + (s.json.attendanceRate || 0), 0) / absentStudents.length
  ),

  studentsAtRisk: absentStudents
    .filter(s => s.json.alertLevel === 'High' || s.json.alertLevel === 'Medium')
    .map(s => `${s.json.studentName} (${s.json.recentAbsences} Absences)`)
    .join(', ') || "None"
};


// Step 3: Return the final report to the next node
return [{ json: attendanceReport }];
